 */
const hasKeyEqualTo = function(obj, key, expectedValue) {
    return obj != null &&
           typeof obj === 'object' &&
           typeof key === 'string' &&
           obj.hasOwnProperty(key) &&
           obj[key] === expectedValue;
};
const safeFunction = fn => typeof fn === 'function' ? fn : x => x;
const out = safeFunction(data.out);
